INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (1, 'A transformação digital impulsionou a eficiência operacional nas organizações, mas expandiu a pegada de carbono devido ao consumo energético de data centers e ao descarte prematuro de hardware. A TI Verde surge como resposta estratégica para mitigar tais impactos. Diante desse cenário, uma diretriz de TI Verde focada na sustentabilidade e eficiência energética é:', 'B', 6, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (1, 'A', 'Aumentar a taxa de substituição de servidores físicos para manter hardware de ponta, ignorando a reciclagem do lixo eletrônico.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (1, 'B', 'Implementar a virtualização de servidores para otimizar o uso do hardware existente e reduzir o consumo de energia dos data centers.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (1, 'C', 'Utilizar exclusivamente refrigeração tradicional em potência máxima para evitar o superaquecimento, descartando soluções de arrefecimento natural.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (1, 'D', 'Priorizar a impressão de documentos digitais em papéis reciclados em detrimento do armazenamento em nuvem.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (1, 'E', 'Desativar políticas de descarte consciente de equipamentos eletrônicos para reduzir custos operacionais com logística reversa.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (2, 'O COBIT 2019 estabelece uma distinção clara entre os conceitos de Governança e Gestão de TI. Enquanto a Governança avalia, direciona e monitora as necessidades dos stakeholders, a Gestão planeja, constrói, executa e monitora as atividades alinhadas à direção estabelecida. Com base nessa estrutura, assinale a atribuição exclusiva da Governança de TI:', 'B', 10, 3);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (2, 'A', 'Desenvolver o plano de continuidade de negócios e testar os procedimentos de backup.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (2, 'B', 'Avaliar as necessidades estratégicas da organização para definir objetivos de negócios e direcionar investimentos de TI.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (2, 'C', 'Configurar os parâmetros de segurança do firewall corporativo e monitorar tráfego.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (2, 'D', 'Executar o suporte técnico de segundo nível para usuários finais da organização.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (2, 'E', 'Gerenciar o orçamento operacional diário do departamento de infraestrutura de TI.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (3, 'A estrutura da ITIL 4 introduziu o Sistema de Valor de Serviço (SVS) e o conceito de "Co-criação de Valor", enfatizando que o valor não é simplesmente entregue pelo provedor ao cliente, mas sim gerado em conjunto. No contexto do ITIL 4, o valor de um serviço de TI é definido por:', 'A', 9, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (3, 'A', 'Uma combinação entre a Utilidade (adequação ao propósito) e a Garantia (adequação ao uso).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (3, 'B', 'Apenas pela redução de custos operacionais proporcionada à equipe de desenvolvimento de software.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (3, 'C', 'Pela quantidade de funcionalidades entregues de acordo com o cronograma original do projeto.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (3, 'D', 'Exclusivamente pela garantia de uptime de 99,99% estipulada em contrato técnico.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (3, 'E', 'Pelo valor monetário investido na aquisição das licenças de software e servidores.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (4, 'A Lei Geral de Proteção de Dados (Lei nº 13.709/2018) estabelece princípios e bases legais para o tratamento de dados pessoais no Brasil. Um gestor de TI precisa adequar o formulário de cadastro de um e-commerce para coletar apenas os dados estritamente necessários à entrega do produto. Essa ação atende diretamente ao princípio da:', 'B', 14, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (4, 'A', 'Finalidade explícita e irrestrita.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (4, 'B', 'Minimização de dados (ou Necessidade).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (4, 'C', 'Transparência retroativa.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (4, 'D', 'Segurança do dado por omissão.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (4, 'E', 'Prevenção contínua de desastres.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (5, 'Uma equipe de desenvolvimento de software adota a metodologia ágil Scrum para gerenciar suas entregas. Durante o ciclo de desenvolvimento, ocorrem reuniões diárias de alinhamento (Daily Scrum) com duração máxima de 15 minutos. O objetivo principal da Daily Scrum é:', 'B', 7, 1);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (5, 'A', 'Aprovar o orçamento da próxima Sprint junto ao cliente e patrocinadores.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (5, 'B', 'Inspecionar o progresso em direção à Meta da Sprint e identificar impedimentos no trabalho da equipe.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (5, 'C', 'Avaliar o desempenho individual dos desenvolvedores para fins de demissão ou promoção.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (5, 'D', 'Redigir a documentação detalhada do código desenvolvido no dia anterior.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (5, 'E', 'Reorganizar todo o Product Backlog e priorizar novamente as histórias de usuário.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (6, 'No gerenciamento de projetos tradicional (PMBOK), a Análise de Valor Agregado (EVA) é uma técnica utilizada para integrar escopo, tempo e custo. Caso o Índice de Desempenho de Custos (IDC ou CPI) de um projeto seja igual a 0,85, o gestor de TI deve concluir que:', 'C', 8, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (6, 'A', 'O projeto está gastando menos recursos financeiros do que o planejado.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (6, 'B', 'O projeto está adiantado em relação ao cronograma estipulado.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (6, 'C', 'O projeto está estourando o orçamento previsto (gastando mais do que o valor do trabalho realizado).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (6, 'D', 'O projeto está com o escopo completamente alinhado às expectativas das partes interessadas.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (6, 'E', 'O projeto possui um índice perfeito de eficiência financeira.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (7, 'O modelo de serviço em nuvem no qual o provedor fornece o ambiente de execução, incluindo sistema operacional, runtimes de linguagem e banco de dados, permitindo que a empresa cliente foque no desenvolvimento e implantação de aplicações sem gerenciar a infraestrutura subjacente, é denominado:', 'B', 11, 1);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (7, 'A', 'IaaS (Infrastructure as a Service).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (7, 'B', 'PaaS (Platform as a Service).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (7, 'C', 'SaaS (Software as a Service).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (7, 'D', 'DaaS (Desktop as a Service).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (7, 'E', 'CaaS (Container as a Service).');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (8, 'A Tríade da Segurança da Informação (CIA) fundamenta os pilares da ISO/IEC 27001. Quando um ataque de Ransomware criptografa o banco de dados de uma empresa e impede o acesso aos sistemas corporativos, o pilar de segurança impactado diretamente é a:', 'C', 13, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (8, 'A', 'Confidencialidade.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (8, 'B', 'Autenticidade.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (8, 'C', 'Disponibilidade.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (8, 'D', 'Não repúdio.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (8, 'E', 'Rastreabilidade.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (9, 'O conceito de DevOps busca integrar as equipes de Desenvolvimento (Dev) e Operações (Ops). Uma das práticas centrais do DevOps é a Integração Contínua (CI), que consiste em:', 'B', 5, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (9, 'A', 'Automatizar a infraestrutura utilizando arquivos de configuração e código.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (9, 'B', 'Automatizar a fusão do código de múltiplos desenvolvedores em um repositório compartilhado com testes automatizados frequentes.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (9, 'C', 'Realizar implantações manuais no ambiente de produção quinzenalmente.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (9, 'D', 'Terceirizar a equipe de testes para garantir a imparcialidade nas revisões de código.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (9, 'E', 'Monitorar o desempenho dos servidores em tempo real utilizando painéis visuais.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (10, 'No contexto de Business Intelligence e Data Warehousing, o processo conhecido como ETL desempenha um papel fundamental na preparação dos dados. A sigla ETL corresponde a:', 'A', 2, 1);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (10, 'A', 'Extract, Transform, Load (Extrair, Transformar, Carregar).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (10, 'B', 'Enterprise Technology Logic (Lógica Tecnológica Empresarial).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (10, 'C', 'Execute, Test, Launch (Executar, Testar, Lançar).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (10, 'D', 'Evaluate, Transfer, Log (Avaliar, Transferir, Registrar).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (10, 'E', 'Export, Translate, Link (Exportar, Traduzir, Vincular).');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (11, 'A arquitetura orientada a microsserviços divide uma aplicação em pequenos serviços independentes que se comunicam através de protocolos leves. Uma vantagem técnica fundamental dessa abordagem sobre uma arquitetura monolítica é:', 'B', 1, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (11, 'A', 'A eliminação da necessidade de utilizar bancos de dados na aplicação.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (11, 'B', 'O escalamento independente de componentes específicos conforme a demanda do sistema.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (11, 'C', 'A garantia de que falhas em um serviço derrubarão imediatamente toda a aplicação para segurança dos dados.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (11, 'D', 'A redução da complexidade na governança e no monitoramento de rede entre os serviços.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (11, 'E', 'A dispensa do uso de APIs de comunicação entre as partes do sistema.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (12, 'No planejamento de Continuidade de Negócios e Recuperação de Desastres (DRP), as métricas RTO (Recovery Time Objective) e RPO (Recovery Point Objective) são críticas. Se uma organização define seu RPO em 2 horas, significa que:', 'B', 3, 3);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (12, 'A', 'O tempo total de parada do sistema não pode ultrapassar 2 horas em hipótese alguma.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (12, 'B', 'A quantidade máxima aceitável de perda de dados corresponde aos dados gerados nas últimas 2 horas.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (12, 'C', 'O sistema deve voltar a operar com 100% da capacidade em até 2 horas após a falha.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (12, 'D', 'As equipes técnicas têm no máximo 2 horas para detectar e notificar a ocorrência de um incidente.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (12, 'E', 'Os backups devem ser realizados a cada 2 dias no ambiente de homologação.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (13, 'Em um contrato de prestação de serviços de TI, o Service Level Agreement (SLA) define os níveis de serviço esperados. Um contrato estabelece um SLA de disponibilidade de 99,9% mensal para um sistema crítico. Se o SLA for descumprido, a consequência direta do ponto de vista do gerenciamento contratual é:', 'B', 4, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (13, 'A', 'O encerramento sumário da empresa contratada sem direito a defesa.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (13, 'B', 'A aplicação de penalidades contratuais preestabelecidas, como multas ou créditos de serviço.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (13, 'C', 'A perda imediata da certificação ISO 27001 da empresa contratante.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (13, 'D', 'A migração automática do sistema para outro provedor de nuvem sem custos.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (13, 'E', 'A obrigatoriedade de reescrever todo o código-fonte da aplicação sem custos adicionais.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (14, 'Uma empresa de médio porte decide integrar seus processos de vendas, atendimento ao cliente e suporte pós-venda em uma única plataforma para obter uma visão centralizada do ciclo de vida do consumidor. O tipo de sistema de informação adequado para essa finalidade é o:', 'B', 15, 1);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (14, 'A', 'ERP (Enterprise Resource Planning).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (14, 'B', 'CRM (Customer Relationship Management).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (14, 'C', 'SCM (Supply Chain Management).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (14, 'D', 'SIG (Sistema de Informação Gerencial puro).');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (14, 'E', 'WMS (Warehouse Management System).');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (15, 'O conceito de Edge Computing (Computação na Borda) surge como uma evolução e complemento à Computação em Nuvem tradicional. A principal finalidade da Edge Computing em ambientes de IoT (Internet das Coisas) é:', 'B', 16, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (15, 'A', 'Centralizar todo o processamento de dados em data centers geograficamente distantes.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (15, 'B', 'Processar os dados mais próximos de onde são gerados para reduzir a latência e o consumo de largura de banda de rede.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (15, 'C', 'Substituir totalmente o uso de criptografia na transmissão de dados ponta a ponta.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (15, 'D', 'Aumentar o consumo de energia dos dispositivos finais para melhorar o processamento local.');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (15, 'E', 'Eliminar a necessidade de conectividade com redes sem fio nos sensores industriais.');
INSERT INTO Questao (id_questao, enunciado, resposta_correta, idEixo, idDificuldade) VALUES (16, 'Em um cenário global caracterizado pela transformação digital acelerada, organizações enfrentam o desafio de alinhar inovação tecnológica à sustentabilidade e responsabilidade social (ESG). Um gestor de TI propõe a implementação de políticas de TI Verde (Green IT) para reduzir a pegada de carbono do datacenter corporativo. Sob a perspectiva da Formação Geral do ENADE, qual medida expressa o alinhamento correto entre ética, eficiência energética e responsabilidade socioambiental?', 'B', 12, 2);
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (16, 'A', 'Desligamento de sistemas essenciais fora do horário comercial sem consulta ao impacto nas operações e stakeholders');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (16, 'B', 'Adoção do ciclo de vida sustentável com consolidação de servidores via virtualização e descarte certificado de e-waste');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (16, 'C', 'Substituição anual preventiva de todo o parque tecnológico para manter equipamentos sempre na faixa de máxima eficiência energética');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (16, 'D', 'Exportação irrestrita de equipamentos obsoletos para países em desenvolvimento sem exigência de tratamento de resíduos');
INSERT INTO Alternativa (idQuestao, letra, texto_alternativa) VALUES (16, 'E', 'Migração total para computação em nuvem sem auditoria das práticas ambientais e fontes de energia dos datacenters terceirizados');
